# frozen_string_literal: true

RSpec.describe 'FieldStruct::Protobuf.proto (scalars)' do
  it 'PB-B21: prints the documented layout exactly' do
    klass = define_struct('Velo::Station') do
      required :district, :string, proto: { number: 1 }
      optional :dock, :string, proto: { number: 2 }
    end
    expect(FieldStruct::Protobuf.proto(klass)).to eq(<<~PROTO)
      // field_struct/velo/station.proto: generated by field_struct-protobuf from Velo::Station.
      // Field numbers come from each field's proto: {number:} option.

      syntax = "proto3";

      package velo;

      message Station {
        optional string district = 1;
        optional string dock = 2;
      }
    PROTO
  end

  it 'PB-B20: omits the package line and its blank line for a top-level class' do
    klass = define_struct('TopLevel') { required :a, :string, proto: { number: 1 } }
    expect(FieldStruct::Protobuf.proto(klass)).to eq(<<~PROTO)
      // field_struct/top_level.proto: generated by field_struct-protobuf from TopLevel.
      // Field numbers come from each field's proto: {number:} option.

      syntax = "proto3";

      message TopLevel {
        optional string a = 1;
      }
    PROTO
  end

  it 'PB-B20: writes repeated, bytes, bool, int64 and double lines in field order' do
    klass = define_struct('Mixed::Row') do
      required :telemetry, :binary, proto: { number: 3 }
      optional :ok, :boolean, proto: { number: 1 }
      optional :n, :integer, proto: { number: 7 }
      optional :charge, :float, proto: { number: 2 }
      optional :labels, :array, of: :string, proto: { number: 5 }
    end
    expect(FieldStruct::Protobuf.proto(klass)).to end_with(<<~PROTO)
      message Row {
        optional bytes telemetry = 3;
        optional bool ok = 1;
        optional int64 n = 7;
        optional double charge = 2;
        repeated string labels = 5;
      }
    PROTO
  end

  it 'PB-B20: ends with a newline and refuses nothing the descriptor accepts' do
    klass = define_struct('One') { required :a, :string, proto: { number: 1 } }
    expect(FieldStruct::Protobuf.proto(klass)).to end_with("}\n")
  end

  describe 'compiled with protoc (PB-I2)' do
    it 'PB-I2: gives protoc an equivalent descriptor for every scalar mapping' do
      klass = define_struct('Check::Scalars') do
        required :bin, :binary, proto: { number: 1 }
        required :str, :string, proto: { number: 2 }
        required :uid, :uuid, proto: { number: 4 }
        required :sym, :symbol, proto: { number: 7 }
        required :dec, :big_decimal, proto: { number: 8 }
        required :dat, :date, proto: { number: 9 }
        required :flg, :boolean, proto: { number: 10 }
        required :int, :integer, proto: { number: 11 }
        required :flt, :float, proto: { number: 12 }
        optional :labels, :array, of: :string, proto: { number: 13 }
        optional :ints, :array, of: :integer, proto: { number: 14 }
        optional :last, :string, proto: { number: 15 }
      end
      expect(ProtocCheck.compile(ProtocCheck.texts([klass]))).to eq(ProtocCheck.ours([klass]))
    end

    it 'PB-I2: compares equal for a top-level class too (no package)' do
      klass = define_struct('TopLevel') { required :a, :string, proto: { number: 1 } }
      expect(ProtocCheck.compile(ProtocCheck.texts([klass]))).to eq(ProtocCheck.ours([klass]))
    end
  end
end
